(function(){
  const L=(id,category,title,level,summary,keywords,description,objectives,sections,code,reference,mistakes,task,question,options,answer,explanation)=>({id,category,title,level,summary,keywords,description,objectives,points:objectives,sections,code,reference,mistakes,task,minutes:Math.max(12,sections.length*5),quiz:{question,options,answer,explanation}});
  const S=(title,body)=>({title,body});
  window.APEX_CURRICULUM=window.APEX_CURRICULUM||{};
  window.APEX_CURRICULUM.html=[
    L('web-foundations','Foundations','How the web and HTML work','Beginner','Understand the journey from a URL to a rendered page.','web browser server http url dom html css javascript','HTML is the structural language of web documents. Understanding how browsers request and interpret a page makes every later topic easier.',
      ['Explain the roles of browser, server, HTTP, and URL','Distinguish HTML structure from CSS presentation and JavaScript behavior','Describe how HTML becomes the Document Object Model','Use browser developer tools to inspect a page'],[
        S('From URL to page','A URL identifies a resource. The browser resolves the domain, connects to a server, sends an HTTP request, receives an HTML response, and parses it. Extra resources such as style sheets, scripts, fonts, and images may trigger more requests.'),
        S('The three core languages','HTML describes meaning and structure: headings, links, forms, articles. CSS controls layout and appearance. JavaScript reads and changes the DOM, responds to events, and communicates with services. A robust page begins with useful HTML before either enhancement is added.'),
        S('Parsing and the DOM','The browser tokenizes HTML and builds a tree of nodes called the DOM. Incorrect nesting may be automatically repaired, sometimes differently from what the author intended. Developer tools show the repaired DOM, while View Source shows the original response.')],
      `<!doctype html>\n<html lang="en">\n<head><title>Apex</title></head>\n<body><h1>How the web works</h1></body>\n</html>`,
      [['URL','Address of a resource on the web'],['HTTP','Protocol used to request and return web resources'],['DOM','Tree representation of the parsed document'],['HTML','Language that describes document structure and meaning']],
      ['Treating HTML, CSS, and JavaScript as interchangeable','Assuming the DOM always matches malformed source code','Opening developer tools only after a bug becomes difficult'],
      'Open a website in developer tools. Identify its document request, inspect one heading in the DOM, and find one CSS and one JavaScript request.',
      'Which object is created when the browser parses HTML?',['A database table','The DOM tree','A DNS zone','A CSS variable'],1,'The parsed document becomes a DOM tree that browser APIs can read and modify.'),

    L('document-structure','Foundations','Document structure and metadata','Beginner','Build a complete, standards-based HTML document.','doctype html head body meta charset viewport title lang','A valid document skeleton supplies the browser, search engines, and assistive technologies with essential information before visible content begins.',
      ['Write the complete HTML document skeleton','Set language, character encoding, viewport, title, and description','Place metadata in head and visible content in body','Understand when link, style, and script belong in head'],[
        S('The root structure','The doctype selects standards mode. The html element wraps the document and its lang attribute declares the primary language. Head stores document metadata; body contains the rendered document. These elements are not decorative boilerplate—their values affect parsing, accessibility, search results, and mobile layout.'),
        S('Essential metadata','Declare UTF-8 near the start of head so characters decode correctly. The viewport declaration makes CSS pixels behave sensibly on mobile devices. A unique title labels the browser tab and often becomes a search-result headline. A concise description can become the search-result summary.'),
        S('Loading resources','link commonly loads style sheets and icons. script loads JavaScript; defer allows an external classic script to run after parsing. style embeds page-specific CSS. Keep the head focused and never put visible headings or paragraphs there.')],
      `<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="description" content="Learn semantic HTML from first principles.">\n  <title>HTML foundations | Apex</title>\n  <link rel="stylesheet" href="styles.css">\n  <script src="app.js" defer></script>\n</head>\n<body>\n  <main><h1>HTML foundations</h1></main>\n</body>\n</html>`,
      [['<!doctype html>','Enables standards mode'],['lang','Declares the document language'],['charset','Selects character encoding'],['viewport','Controls the mobile viewport'],['title','Names the document and browser tab']],
      ['Omitting lang or using the wrong language code','Using the same vague title on every page','Putting visible page content inside head'],
      'Create a complete document for a recipe page with accurate language, title, description, viewport, and one visible main heading.',
      'Where should the page description meta element be placed?',['Inside body','Inside main','Inside head','After html'],2,'Document metadata belongs inside the head element.'),

    L('syntax-elements','Foundations','Elements, tags, attributes, and nesting','Beginner','Master the grammar used by every HTML element.','element tag attribute nesting void boolean quoted entity','HTML uses elements to mark meaning. Correct syntax and nesting make documents predictable, readable, and easier to maintain.',
      ['Distinguish elements, start tags, end tags, content, and attributes','Nest elements without overlap','Recognize void and boolean attributes','Escape reserved characters with character references'],[
        S('Anatomy of an element','A normal element contains a start tag, content, and an end tag. Attributes add information to the start tag as name-value pairs. Attribute order usually does not matter, but consistent lowercase names, quoted values, and indentation make source easier to review.'),
        S('Nesting rules','Elements form a tree, so the last element opened should be the first closed. Some elements allow only specific children: ul expects li, table uses table-specific elements, and p cannot contain large structural sections. The browser repairs invalid trees, but relying on repair creates surprising DOM structures.'),
        S('Void, boolean, and escaped syntax','Void elements such as img, input, meta, link, br, and hr do not have end tags. A boolean attribute is true when present: disabled and disabled="disabled" mean the same thing. Use &lt;, &gt;, &amp;, &quot;, and numeric references when a reserved character must appear as text.')],
      `<button type="button" disabled>\n  Saving…\n</button>\n<img src="diagram.png" alt="Element nesting diagram" width="640" height="360">\n<p>Use &lt;main&gt; for the primary content.</p>`,
      [['element','Complete semantic unit'],['tag','Markup that opens or closes an element'],['attribute','Extra information on a start tag'],['void element','Element with no closing tag'],['boolean attribute','True when the attribute is present']],
      ['Overlapping tags such as <strong><em>text</strong></em>','Writing closing tags for void elements as if they contained content','Repeating the same id on multiple elements'],
      'Correct a deliberately malformed snippet containing overlapping tags, an unquoted value with spaces, and an incorrectly closed img element.',
      'Which is a void element?',['section','strong','img','button'],2,'img cannot contain child content and has no closing tag.'),

    L('text-semantics','Content','Headings, paragraphs, and text semantics','Beginner','Give written content a logical hierarchy and precise meaning.','heading h1 h2 paragraph strong em mark small quote code pre whitespace','Semantic text elements communicate structure beyond visual styling.',
      ['Create a logical heading hierarchy','Choose semantic inline elements for importance, emphasis, quotations, and code','Understand HTML whitespace collapsing','Use preformatted text only when spacing is meaningful'],[
        S('Heading hierarchy','h1 through h6 represent nested section levels, not font sizes. Start with the page topic and descend one level for direct subsections. Skipping levels can confuse people who navigate with a screen-reader heading list. Style headings with CSS instead of choosing an inaccurate level.'),
        S('Meaningful inline text','strong marks importance; em adds stress that can change meaning. mark highlights relevance, small is side commentary, code identifies code, kbd represents user input, samp represents program output, sub and sup mark scientific or typographic position. Do not use b or i when a semantic element better describes the reason.'),
        S('Whitespace and quotations','Normal HTML collapses runs of spaces and line breaks. Use paragraphs and CSS for spacing, not repeated br elements or non-breaking spaces. Use blockquote for an extended quotation and q for an inline quote; cite can name a work, while the cite attribute may hold its source URL.')],
      `<article>\n  <h1>Accessible forms</h1>\n  <p>A <strong>label is required</strong> for every field.</p>\n  <h2>Keyboard testing</h2>\n  <p>Press <kbd>Tab</kbd> and check the <em>visible</em> focus order.</p>\n  <blockquote cite="https://www.w3.org/">\n    <p>The web is for everyone.</p>\n  </blockquote>\n</article>`,
      [['strong','Strong importance'],['em','Stress emphasis'],['mark','Relevant highlight'],['code','Code fragment'],['kbd','User input'],['blockquote','Extended quotation']],
      ['Choosing headings because of default size','Using br repeatedly to create layout spacing','Using strong only to make text visually bold'],
      'Turn a plain article into semantic HTML with a correct heading outline, important warning, keyboard shortcut, quotation, and inline code.',
      'Why should heading levels be chosen?',['For their default size','To express document hierarchy','To add margins','To improve color contrast'],1,'Heading levels describe the hierarchy of sections; CSS controls appearance.'),

    L('links-urls','Content','Links, URLs, and navigation','Beginner','Create safe, descriptive navigation within and between sites.','a href url relative absolute fragment mailto tel download target rel nav','Links are the connective tissue of the web. Good links reveal their destination, work with keyboards, and use the right URL form.',
      ['Write absolute, relative, root-relative, fragment, email, and telephone links','Create labeled navigation regions','Use target and rel safely','Design link text that makes sense out of context'],[
        S('URL types','An absolute URL includes scheme and host. A relative URL is resolved from the current document; ../ moves to a parent directory and / starts at the site root. A #fragment targets an element id on the same page. mailto and tel request suitable applications but may not be available everywhere.'),
        S('Meaningful link text','A link should describe its destination or action without surrounding text. “Read the forms guide” is stronger than “click here.” Do not place one interactive control inside another. A link navigates to a resource; a button performs an action on the current interface.'),
        S('New contexts and relationships','target="_blank" opens a new context and should be used sparingly because it changes expected behavior. Modern browsers protect new tabs, but rel="noopener" remains a clear security signal. rel values such as external, author, next, prev, nofollow, and noreferrer describe the relationship.')],
      `<nav aria-label="Course sections">\n  <a href="/courses/html/">HTML course</a>\n  <a href="forms.html">Forms lesson</a>\n  <a href="#practice">Jump to practice</a>\n  <a href="https://developer.mozilla.org/" target="_blank" rel="noopener external">MDN reference (opens a new tab)</a>\n</nav>`,
      [['absolute URL','Full scheme, host, and path'],['relative URL','Resolved from the current document'],['fragment','Targets an id with #'],['href','Link destination'],['rel','Relationship and security hints']],
      ['Using “click here” for every destination','Using a link when a button should trigger an action','Breaking relative links by moving files without updating paths'],
      'Build primary navigation, breadcrumbs, an in-page table of contents, and one external reference link with clear text.',
      'Which element should submit a form?',['An a element','A button element','A nav element','A span element'],1,'Submitting is an action, so a button is the appropriate native control.'),

    L('images-responsive','Media','Images, figures, and responsive sources','Intermediate','Deliver meaningful images efficiently on every screen.','img src alt figure figcaption picture source srcset sizes lazy decoding','Images need accessible alternatives, stable dimensions, appropriate formats, and sources matched to device needs.',
      ['Write alt text based on an image’s purpose','Reserve layout space with width and height','Use srcset and sizes for resolution selection','Use picture for art direction and modern formats'],[
        S('Alternative text decisions','Describe information that a sighted user gains and surrounding text does not already provide. Use alt="" for decorative images so assistive technology skips them. For a linked image, describe the link’s action. Complex charts need nearby text or a longer data description, not an enormous alt value.'),
        S('Performance and stability','Set intrinsic width and height so the browser can calculate aspect ratio before download. loading="lazy" is useful for off-screen images but not the main above-the-fold image. decoding="async" can prevent decoding work from delaying other rendering. Choose SVG for scalable graphics, WebP or AVIF for efficient photos where supported, and PNG when lossless transparency is needed.'),
        S('Responsive selection','srcset with width descriptors offers multiple file sizes; sizes tells the browser the expected rendered width. picture allows art direction—different crops—or type selection. The img element remains the required fallback and owns the alt text.')],
      `<picture>\n  <source type="image/avif" srcset="summit-480.avif 480w, summit-960.avif 960w">\n  <source media="(min-width: 800px)" srcset="summit-wide.jpg">\n  <img src="summit-square.jpg" srcset="summit-square.jpg 480w, summit-large.jpg 960w" sizes="(min-width: 800px) 50vw, 100vw" alt="Two learners reviewing code at a mountain overlook" width="960" height="640" loading="lazy">\n</picture>`,
      [['alt=""','Marks a decorative image'],['srcset','Candidate image sources'],['sizes','Expected rendered size'],['picture','Format choice or art direction'],['loading="lazy"','Defers an off-screen image']],
      ['Writing “image of” in ordinary alt text','Omitting dimensions and causing layout shift','Lazy-loading the page’s most important image'],
      'Create a responsive figure with two file sizes, a modern-format source, useful alt text, fixed dimensions, and a caption.',
      'Where does alternative text belong when picture is used?',['On every source','On the img fallback','On picture','On figcaption only'],1,'The img element owns the alt text and acts as the fallback.'),

    L('lists','Content','Lists and grouped information','Beginner','Represent sequences, collections, and name-value pairs correctly.','ul ol li dl dt dd reversed start value nested menu','HTML provides different list structures based on whether order and term-description relationships matter.',
      ['Choose between unordered, ordered, and description lists','Nest lists correctly inside list items','Control ordered list numbering when content requires it','Mark navigation and menus without misusing list semantics'],[
        S('Three list types','ul is for related items whose order is not essential. ol is for steps, rankings, and sequences where order changes meaning. dl contains groups of dt terms and dd descriptions and works for glossaries, metadata, and question-answer pairs.'),
        S('Nesting and numbering','A nested list belongs inside the parent li, after its text. ol supports start, reversed, and a value attribute on individual li elements. Use these only when numbering is part of the content; use CSS counters for decorative numbering.'),
        S('Lists in interfaces','Navigation links are often placed in a list inside nav, but a list is not mandatory when it adds no useful grouping. The menu element is semantically similar to ul and is rarely needed. Do not use empty list items or lists only to create indentation.')],
      `<h2>Publish a page</h2>\n<ol>\n  <li>Validate the HTML</li>\n  <li>Test with:\n    <ul><li>Keyboard</li><li>Small screen</li><li>Screen reader</li></ul>\n  </li>\n  <li>Deploy the files</li>\n</ol>\n<dl><dt>DOM</dt><dd>The parsed document tree.</dd></dl>`,
      [['ul','Unordered collection'],['ol','Ordered sequence'],['li','One list item'],['dl','Description list'],['dt / dd','Term and description']],
      ['Placing a nested ul beside an li instead of inside it','Using paragraphs with manual bullets instead of a list','Using a description list to fake a two-column layout'],
      'Create a course outline with ordered modules, nested lesson lists, and a small glossary using dl.',
      'Which list is best for a glossary?',['ul','ol','dl','nav'],2,'A description list directly associates terms with their descriptions.'),

    L('tables','Data','Accessible data tables','Intermediate','Build tables that communicate relationships between headers and cells.','table caption thead tbody tfoot tr th td scope colspan rowspan colgroup','Tables are for multidimensional data. Captions, structural groups, and scoped header cells make complex data understandable.',
      ['Create captions, row groups, rows, headers, and data cells','Associate headers with data using scope','Use spanning only when the data model requires it','Make wide tables usable on small screens'],[
        S('Structure and purpose','table contains an optional caption, optional colgroup, and rows commonly grouped in thead, tbody, and tfoot. th identifies a header and td identifies data. Do not use tables to arrange page layout; that creates a misleading reading order.'),
        S('Header association','scope="col" associates a header with its column; scope="row" associates it with its row. For multi-level headers, colgroup and rowgroup may help. Very complex irregular tables may require explicit id and headers relationships, but a simpler table design is usually better.'),
        S('Responsive and usable tables','Keep labels concise, align numeric values consistently, and include units in headers. On narrow screens, place the table inside an overflow container rather than hiding columns without explanation. A visible caption explains what the dataset represents.')],
      `<div class="table-scroll" tabindex="0">\n<table>\n  <caption>Course completion by month</caption>\n  <thead><tr><th scope="col">Month</th><th scope="col">HTML</th><th scope="col">Python</th></tr></thead>\n  <tbody><tr><th scope="row">January</th><td>42</td><td>35</td></tr><tr><th scope="row">February</th><td>51</td><td>47</td></tr></tbody>\n</table>\n</div>`,
      [['caption','Accessible table name and context'],['th','Header cell'],['td','Data cell'],['scope="col"','Header applies down a column'],['scope="row"','Header applies across a row']],
      ['Leaving header cells as td because they look the same after styling','Omitting a caption when the table needs context','Using colspan to force a visual layout unrelated to data'],
      'Build a timetable with day columns, time row headers, a caption, and a horizontally scrollable wrapper.',
      'What does scope="row" mean?',['The header labels cells across its row','The row spans the full table','The header labels its column','The row is hidden'],0,'A row-scoped header identifies the data cells that follow across that row.'),

    L('forms-foundations','Forms','Form structure, labels, and submission','Intermediate','Build forms people can understand, complete, and submit.','form action method get post label input name value button fieldset legend autocomplete','A form is a data-entry workflow. Clear labels, logical groups, suitable controls, and predictable submission matter more than visual decoration.',
      ['Connect every field with a visible label','Understand name, value, action, method, and form data','Group related controls with fieldset and legend','Choose button types deliberately'],[
        S('Submission model','form action is the destination and method is usually GET for retrieval or POST for a state-changing submission. Only successful controls with a name contribute data. The submitted name-value pairs depend on each control’s current value.'),
        S('Labels and instructions','A label’s for value matches the control id, increasing the clickable area and providing an accessible name. Keep instructions near the field and identify required formats before an error occurs. Placeholder text is a hint, not a replacement for a label.'),
        S('Grouping and buttons','fieldset and legend name a related group, especially radio buttons or a complex address. A button inside a form defaults to submit, so use type="button" for non-submit actions and type="reset" only with great care because it can erase work.')],
      `<form action="/signup" method="post">\n  <div><label for="full-name">Full name</label><input id="full-name" name="full_name" autocomplete="name" required></div>\n  <fieldset><legend>Study plan</legend>\n    <label><input type="radio" name="plan" value="daily" required> Daily</label>\n    <label><input type="radio" name="plan" value="weekends"> Weekends</label>\n  </fieldset>\n  <button type="submit">Create plan</button>\n</form>`,
      [['action','Submission destination'],['method','HTTP submission method'],['name','Key included in submitted data'],['label','Accessible control name'],['fieldset / legend','Related control group']],
      ['Using placeholder as the only label','Forgetting name and wondering why data is missing','Allowing an ordinary utility button to submit the form accidentally'],
      'Build a contact form with name, email, subject, message, contact preference, autocomplete hints, and a clearly named submit button.',
      'Which attribute supplies the key in submitted form data?',['id','class','name','placeholder'],2,'The name attribute becomes the key paired with the control value.'),

    L('input-types','Forms','Input types and selection controls','Intermediate','Choose native controls that match the data being collected.','input email number date time file checkbox radio select option textarea datalist range color','Native input types provide useful keyboards, parsing, semantics, and validation when used for the right kind of data.',
      ['Choose appropriate text, numeric, date, choice, and upload controls','Understand checkbox and radio submission behavior','Build select, datalist, and textarea controls','Use accept, multiple, inputmode, and autocomplete appropriately'],[
        S('Text-like controls','text is the general single-line control. email, url, tel, search, and password express intent and may change mobile keyboards or validation. inputmode hints at a keyboard without changing the data type. textarea handles multiline plain text.'),
        S('Numbers, dates, and ranges','number is for quantities that users may increment, not every digit string—postal codes and card numbers are text. date and time controls vary by platform but submit standardized values. range is useful when an approximate value is acceptable and its current value is also shown.'),
        S('Choices and files','Checkboxes represent independent booleans or multiple selections; checked boxes submit their value, unchecked boxes submit nothing. Radios sharing a name form one choice group. select is good for a constrained list, while datalist offers suggestions without restricting input. File inputs use accept as a hint, not a security check.')],
      `<label for="email">Email</label>\n<input id="email" name="email" type="email" autocomplete="email" required>\n<label for="experience">Years of experience</label>\n<input id="experience" name="experience" type="number" min="0" max="80" step="1">\n<label for="track">Track</label>\n<select id="track" name="track"><option value="">Choose one</option><option value="frontend">Frontend</option><option value="data">Data</option></select>`,
      [['email','Email address with format validation'],['number','Incrementable numeric quantity'],['radio','One choice in a named group'],['checkbox','Independent on/off choice'],['datalist','Suggestions for a text-like input']],
      ['Using number for identifiers that may start with zero','Expecting accept to securely validate uploaded files','Giving every radio button a different name'],
      'Create a profile form using at least six suitable control types and explain why each type fits its data.',
      'Which control is best for a postal code?',['number','range','text with inputmode','date'],2,'A postal code is an identifier, not a quantity, and may contain letters or leading zeroes.'),

    L('form-validation','Forms','Constraint validation and helpful errors','Advanced','Prevent avoidable errors without blocking legitimate input.','required minlength maxlength min max step pattern validity aria-describedby error','HTML constraint validation can catch many problems, but good validation combines native rules, clear messages, server checks, and recovery guidance.',
      ['Use required, length, range, type, and pattern constraints','Explain client-side versus server-side validation','Connect instructions and errors to controls','Design errors that identify both the problem and the fix'],[
        S('Native constraints','required rejects empty values; minlength and maxlength constrain text; min, max, and step constrain numeric or date-like values; type can validate email or URL syntax; pattern applies a regular expression to the entire value. Avoid patterns stricter than the real business rule.'),
        S('Error communication','Do not rely on red borders alone. Place a specific message near the field, connect it with aria-describedby when custom handling is used, preserve the user’s input, and move focus or provide a summary when submission fails. Validate at a useful time—usually after interaction or submit, not on every first keystroke.'),
        S('Security boundary','Browser validation improves usability but can be bypassed. The server must validate again, apply authorization, normalize carefully, and use safe database operations. Never trust hidden inputs, disabled interfaces, or client JavaScript as security controls.')],
      `<label for="username">Username</label>\n<p id="username-help">Use 3–20 letters, numbers, or underscores.</p>\n<input id="username" name="username" required minlength="3" maxlength="20" pattern="[A-Za-z0-9_]+" aria-describedby="username-help username-error">\n<p id="username-error" role="alert" hidden>Use only letters, numbers, or underscores.</p>`,
      [['required','Value must not be empty'],['pattern','Full-value regular expression'],['aria-describedby','Associates help and errors'],['novalidate','Disables browser constraint UI'],['ValidityState','JavaScript validation state object']],
      ['Assuming client validation protects a server','Showing “invalid input” without explaining how to fix it','Rejecting real names, addresses, or passwords with unnecessary patterns'],
      'Add native constraints and accessible error guidance to a sign-up form, then list the equivalent server-side checks.',
      'Why must a server repeat validation?',['CSS may fail','Client checks can be bypassed','Labels are optional','GET never submits data'],1,'A request can be created without using the page, so the server must enforce every trusted rule.'),

    L('semantic-layout','Semantics','Semantic page regions and content models','Intermediate','Choose elements that describe the role of each content region.','header footer main nav article section aside address div span content model','Semantic structure helps browsers, search systems, and assistive technology understand a document before CSS is applied.',
      ['Use header, nav, main, article, section, aside, and footer accurately','Distinguish article from section','Use div and span only when no semantic element fits','Respect element content models and landmark rules'],[
        S('Landmark elements','main contains the page’s unique primary content and normally appears once. nav encloses a major navigation block and should be labeled when several nav regions exist. header and footer belong to the nearest sectioning ancestor or the page body, so an article can have its own header and footer.'),
        S('Article, section, and aside','article is self-contained enough to be distributed or reused: a post, comment, product card, or news story. section groups related content and almost always needs a heading. aside is complementary content whose removal would not break the main flow.'),
        S('Generic containers','div and span carry no meaning and are correct for styling or scripting hooks when no semantic element fits. Do not replace every div automatically; ask what the region is and whether its meaning is useful. Semantic HTML does not remove the need for a sensible reading order.')],
      `<body>\n<header><nav aria-label="Primary">…</nav></header>\n<main>\n  <article>\n    <header><h1>Database keys explained</h1><p>Updated <time datetime="2026-09-29">29 September 2026</time></p></header>\n    <section aria-labelledby="primary-key"><h2 id="primary-key">Primary keys</h2>…</section>\n    <aside aria-label="Related lessons">…</aside>\n  </article>\n</main>\n<footer>…</footer>\n</body>`,
      [['main','Unique primary page content'],['article','Self-contained composition'],['section','Thematic group with a heading'],['aside','Complementary content'],['div / span','Generic block / inline containers']],
      ['Using section as a styling wrapper with no heading','Putting repeated site navigation outside a labeled nav','Adding main inside every article card'],
      'Replace generic containers in a news page with an accurate semantic structure and explain each choice.',
      'Which element best represents a reusable independent blog post?',['section','div','article','aside'],2,'article represents a self-contained composition that can stand on its own.'),

    L('accessibility','Semantics','Accessibility foundations','Essential','Create perceivable, operable, understandable, and robust pages.','accessibility wcag screen reader keyboard focus aria name role value contrast zoom','Accessible HTML begins with native semantics and supports different senses, input methods, reading needs, and technologies.',
      ['Apply the POUR accessibility principles','Use native controls and accessible names','Maintain keyboard access and visible focus','Understand when ARIA helps and when it harms'],[
        S('Perceivable and understandable','Provide text alternatives for non-text information, captions for meaningful audio, sufficient contrast, and layouts that survive zoom and reflow. Use clear labels, predictable navigation, plain instructions, and explicit error recovery. Language declarations help pronunciation.'),
        S('Keyboard and focus','Every interactive control must work without a mouse. Keep DOM order aligned with the intended reading and focus order. Never remove focus outlines without a strong replacement. Move focus only when an interaction changes context in a way that requires it, such as opening a modal dialog.'),
        S('Native HTML before ARIA','A button already exposes button role, keyboard activation, focus behavior, name, and state. A clickable div exposes none of these. ARIA can add names, relationships, and states but cannot create missing keyboard behavior. The first rule of ARIA is to use a native element when one exists.')],
      `<button type="button" aria-expanded="false" aria-controls="lesson-details">Show lesson details</button>\n<section id="lesson-details" hidden>\n  <h2>Lesson details</h2>\n  <p>Estimated time: 15 minutes.</p>\n</section>`,
      [['accessible name','Text announced as a control’s name'],['focus order','Sequence reached with keyboard navigation'],['landmark','Major navigable page region'],['ARIA','Attributes that supplement accessibility semantics'],['WCAG','Web Content Accessibility Guidelines']],
      ['Making a div clickable instead of using button','Adding aria-label that conflicts with visible text','Hiding focused content or trapping keyboard focus outside a modal'],
      'Audit one page using keyboard-only navigation, 200% zoom, headings, landmarks, labels, alt text, and automated checks; record issues and fixes.',
      'What should you try before adding role="button" to a div?',['Add tabindex','Use a native button','Add a click handler','Hide it from screen readers'],1,'A native button supplies semantics and interaction behavior with fewer failure points.'),

    L('media','Media','Audio, video, captions, and tracks','Intermediate','Embed media with controls, alternatives, and efficient sources.','audio video source track captions subtitles descriptions poster preload autoplay','Native media elements can provide playback controls and synchronized text tracks without a plugin.',
      ['Embed audio and video with multiple sources','Add captions and subtitles with WebVTT tracks','Choose poster and preload behavior','Avoid inaccessible autoplay and missing alternatives'],[
        S('Sources and fallback','audio and video can use src directly or multiple source children with type hints. The browser selects the first supported source. Text between the tags is fallback content, but a linked transcript is often a more useful alternative.'),
        S('Text tracks','track kind="captions" provides same-language dialogue and important sound information; subtitles translate dialogue; descriptions narrate visual information when supported; chapters aid navigation. Tracks use WebVTT files and should have srclang and label. Use default on the preferred track when appropriate.'),
        S('Playback behavior','controls gives users essential play, pause, volume, and seeking. poster provides a video placeholder. preload is a hint: none minimizes initial transfer, metadata loads dimensions and duration, auto permits more. Avoid autoplay with sound; even muted autoplay can distract or consume data.')],
      `<video controls width="960" height="540" poster="lesson-poster.jpg" preload="metadata">\n  <source src="lesson.webm" type="video/webm">\n  <source src="lesson.mp4" type="video/mp4">\n  <track kind="captions" src="lesson-en.vtt" srclang="en" label="English" default>\n  <p><a href="lesson-transcript.html">Read the transcript</a>.</p>\n</video>`,
      [['controls','Native playback interface'],['poster','Video placeholder image'],['preload','Resource loading hint'],['captions','Dialogue plus meaningful sounds'],['subtitles','Translated dialogue']],
      ['Publishing speech without accurate captions','Removing controls from essential media','Using autoplay as the only way media starts'],
      'Create a training video embed with two source formats, captions, poster, dimensions, metadata preload, and transcript link.',
      'Which track kind includes dialogue and important sounds in the same language?',['subtitles','captions','chapters','metadata'],1,'Captions include dialogue and non-speech audio needed to understand the media.'),

    L('embedded-content','Media','Iframes, embeds, maps, and sandboxing','Advanced','Embed external documents without giving them unnecessary power.','iframe src title sandbox allow loading referrerpolicy embed object security','An iframe creates a separate browsing context. Useful embeds require a title, fixed dimensions, constrained permissions, and a fallback plan.',
      ['Give every meaningful iframe an accessible title','Restrict embedded code with sandbox and permissions policy','Use lazy loading and stable dimensions','Understand cross-origin isolation and communication limits'],[
        S('Iframe purpose and naming','iframe embeds another page, such as a map, video player, document, or trusted widget. title names its purpose for assistive technology. width and height reserve space. loading="lazy" can defer off-screen embeds, which are often expensive.'),
        S('Sandbox and permissions','sandbox removes capabilities unless tokens add them back. Avoid combining allow-scripts and allow-same-origin for untrusted same-origin content because it can weaken the sandbox. The allow attribute limits powerful features such as camera, microphone, fullscreen, or geolocation.'),
        S('Origins and communication','Same-origin policy prevents arbitrary access between documents from different origins. Cross-origin frames can communicate deliberately with postMessage, but receivers must verify event.origin and validate message content. Do not embed content that has unclear ownership or privacy behavior.')],
      `<iframe src="https://example.com/course-map" title="Interactive map of course locations" width="800" height="500" loading="lazy" sandbox="allow-scripts" referrerpolicy="strict-origin-when-cross-origin"></iframe>`,
      [['iframe','Embedded browsing context'],['sandbox','Removes capabilities by default'],['allow','Permissions policy for features'],['postMessage','Controlled cross-context messaging'],['same-origin policy','Restricts access between origins']],
      ['Using an iframe without a useful title','Granting every sandbox token for convenience','Trusting postMessage data without checking its origin'],
      'Review an existing video or map embed and reduce its permissions, add a title, dimensions, loading strategy, and privacy explanation.',
      'What does sandbox do when supplied with no tokens?',['Grants every feature','Applies a strong set of restrictions','Hides the iframe','Makes it same-origin'],1,'An empty sandbox attribute applies restrictions; tokens selectively restore capabilities.'),

    L('metadata-seo','Discovery','Metadata, search, and sharing','Intermediate','Help search engines and sharing tools represent each page accurately.','seo title description canonical robots open graph social metadata link rel','Good discovery metadata describes real page content and avoids duplicate or misleading representations.',
      ['Write specific titles and descriptions','Declare canonical URLs and indexing instructions appropriately','Understand structured headings and link text as SEO signals','Add Open Graph metadata only with accurate share content'],[
        S('Search result fundamentals','Search systems use many signals, but a descriptive title, useful main heading, meaningful text, internal links, and accessible structure form the foundation. A meta description may be used as a snippet but is not a guaranteed ranking or display instruction.'),
        S('Canonical and robots controls','rel="canonical" identifies the preferred URL when duplicate routes exist. A robots meta value can request noindex or control snippets, but it is not access control. robots.txt manages crawling hints, not confidentiality. Private information requires authentication.'),
        S('Social metadata','Open Graph properties commonly include og:title, og:description, og:type, og:url, and og:image. Values should match the page rather than advertise unrelated content. Provide an absolute image URL and a meaningful alt property when an image is used.')],
      `<head>\n  <title>HTML forms: labels and validation | Apex</title>\n  <meta name="description" content="Learn to build labeled, validated, accessible HTML forms with worked examples.">\n  <link rel="canonical" href="https://example.com/html/forms">\n  <meta property="og:title" content="HTML forms: labels and validation">\n  <meta property="og:type" content="article">\n  <meta property="og:url" content="https://example.com/html/forms">\n</head>`,
      [['canonical','Preferred URL for duplicate content'],['robots noindex','Requests exclusion from search results'],['meta description','Candidate search-result summary'],['Open Graph','Social sharing metadata vocabulary']],
      ['Using the same title and description everywhere','Treating robots directives as security','Adding misleading keywords that the page never teaches'],
      'Write unique discovery metadata for three lessons and explain how their titles differ from their h1 headings.',
      'What protects private content?',['robots.txt','meta noindex','Authentication and authorization','canonical'],2,'Crawler directives are hints; access control must be enforced by the application.'),

    L('interactive-elements','Interaction','Details, dialog, popover, and native disclosure','Advanced','Use built-in interactive elements before recreating them with scripts.','details summary dialog showModal popover command closedby inert','Modern HTML includes disclosure, dialog, and popover primitives with useful semantics and browser behavior.',
      ['Create accordions with details and summary','Open and close modal or non-modal dialogs','Use the popover attribute for lightweight top-layer content','Manage focus, labels, dismissal, and return behavior'],[
        S('Disclosure with details','details contains a summary followed by the disclosed content. It supports an open attribute and toggle event. Multiple details can share a name in supporting browsers for accordion-like exclusive expansion. The summary must remain understandable when the content is closed.'),
        S('Dialog behavior','dialog represents a focused window. showModal() places it in the top layer, makes the rest of the page inert, and expects a close path. Label it with a heading, provide a visible close or cancel action, and return focus logically. A form with method="dialog" can close it and set returnValue.'),
        S('Popover behavior','The popover attribute creates non-modal top-layer content with light-dismiss behavior. A button can use popovertarget without JavaScript. Popovers suit menus, teaching tips, and pickers; critical confirmations usually need a modal dialog instead.')],
      `<button type="button" popovertarget="shortcut-help">Keyboard shortcuts</button>\n<div id="shortcut-help" popover>\n  <h2>Keyboard shortcuts</h2><p><kbd>Ctrl</kbd> + <kbd>Enter</kbd> checks code.</p>\n</div>\n<details><summary>Why use semantic HTML?</summary><p>It gives content meaning before styling.</p></details>`,
      [['details / summary','Native disclosure'],['dialog.showModal()','Opens a modal dialog'],['method="dialog"','Closes a dialog through form submission'],['popover','Non-modal top-layer content'],['popovertarget','Declarative popover control']],
      ['Building an accordion from clickable div elements','Opening a modal with no keyboard-accessible close control','Using a popover for a destructive confirmation that demands attention'],
      'Build an FAQ with details, a shortcut-help popover, and a labeled confirmation dialog with cancel and confirm actions.',
      'Which primitive is best for optional non-modal teaching help?',['A modal dialog','A popover','A new browser window','A disabled button'],1,'A popover provides lightweight top-layer content without making the page inert.'),

    L('global-attributes','Reference','Global attributes, data, and microdata','Intermediate','Use attributes shared across HTML elements without misusing them.','id class title hidden tabindex accesskey data dataset dir lang translate contenteditable draggable','Global attributes provide identifiers, styling hooks, language direction, visibility, editing, and custom data across many elements.',
      ['Use id and class for different purposes','Store non-sensitive custom values with data attributes','Apply lang, dir, hidden, tabindex, and contenteditable correctly','Avoid title and accesskey as essential instruction mechanisms'],[
        S('Identity and grouping','id must be unique and is used by fragments, labels, ARIA relationships, and scripts. class is a reusable set of tokens for styling or behavior. Avoid selectors that encode fragile document position when a stable class expresses intent.'),
        S('Language, direction, and visibility','lang can change on a phrase in another language. dir may be ltr, rtl, or auto and should reflect text direction. hidden removes content from normal presentation; do not use it for content that must remain available to assistive technology while visually hidden.'),
        S('Custom data and interaction','data-* values are strings available through dataset and are visible to anyone who can inspect the page. contenteditable creates an editing surface but needs careful keyboard, paste, validation, and persistence design. tabindex="0" joins natural order; positive tabindex values create confusing order and should be avoided.')],
      `<article id="lesson-keys" class="lesson" data-course="dbms" data-level="intermediate" lang="en">\n  <h2>Database keys</h2>\n  <p lang="fr">clé primaire</p>\n</article>\n<script>\n  const lesson = document.querySelector('.lesson');\n  console.log(lesson.dataset.course);\n<\/script>`,
      [['id','Unique document identifier'],['class','Reusable token list'],['data-*','Custom non-sensitive string data'],['lang','Content language'],['dir','Text direction'],['tabindex="0"','Adds programmatic control to natural focus order']],
      ['Repeating an id across cards','Storing secrets in data attributes','Using positive tabindex to force a visual order'],
      'Design markup for a multilingual lesson card with stable ids, reusable classes, language changes, and safe data attributes.',
      'Which attribute must be unique in a document?',['class','data-topic','id','lang'],2,'An id identifies one element and must not be repeated.'),

    L('scripts-modules','Integration','Scripts, modules, templates, and noscript','Advanced','Connect behavior without blocking or destroying useful HTML.','script async defer module nomodule template noscript domcontentloaded','Script loading strategy affects parsing, execution order, performance, and progressive enhancement.',
      ['Compare classic, defer, async, and module scripts','Choose a loading strategy based on dependencies','Use template for inert reusable fragments','Provide meaningful baseline content when scripts fail'],[
        S('Classic script loading','A classic script without attributes blocks parsing while it downloads and runs. defer downloads in parallel, preserves document order, and runs after parsing before DOMContentLoaded. async downloads in parallel and runs as soon as ready, so order is unpredictable and it suits independent scripts.'),
        S('JavaScript modules','type="module" scripts are deferred automatically, use strict mode, and support import and export. Each module runs once and has its own scope. Cross-origin module requests use CORS. Use a bundler only when project needs justify it; native modules work well for many small applications.'),
        S('Templates and resilience','template content is parsed but inert until cloned by JavaScript. noscript can explain a missing enhancement, but the better baseline is often useful HTML that already works. Scripts should enhance links, forms, and content instead of replacing them with blank loading shells when avoidable.')],
      `<template id="topic-card">\n  <article class="topic"><h2></h2><p></p></article>\n</template>\n<script type="module">\n  import { renderTopics } from './topics.js';\n  renderTopics(document.querySelector('#topic-card'));\n<\/script>`,
      [['defer','Ordered classic scripts after parsing'],['async','Independent classic script when ready'],['type="module"','Deferred ES module graph'],['template','Inert reusable DOM fragment'],['noscript','Fallback content when scripting is unavailable']],
      ['Using async for scripts that depend on one another','Waiting for DOMContentLoaded inside a module that already runs after parsing','Delivering a blank page when enhancement code fails'],
      'Load an independent analytics script, an ordered application script, and a module correctly; add a template-driven card without losing baseline content.',
      'Which loading mode preserves order for classic scripts and waits until parsing finishes?',['async','defer','preload','nomodule'],1,'defer scripts execute in document order after HTML parsing.'),

    L('internationalization','Quality','Language, direction, dates, and international text','Advanced','Create documents that work across languages and writing systems.','i18n lang dir bdi bdo time datetime ruby wbr translate','International HTML requires correct language metadata, bidirectional isolation, machine-readable dates, and content that does not assume one culture.',
      ['Mark document and inline language changes','Handle right-to-left and user-generated bidirectional text','Represent dates and times with machine-readable values','Use ruby, bdi, bdo, and wbr for specialized text needs'],[
        S('Language declaration','Set html lang to the primary language and override it on phrases in another language. This affects pronunciation, spell checking, translation, and font selection. Use valid BCP 47 tags such as en, en-IN, hi, or ar.'),
        S('Bidirectional content','dir="rtl" sets right-to-left direction; dir="auto" lets the first strong character decide, which is useful for user-generated text. bdi isolates an unknown-direction value from surrounding punctuation. bdo intentionally overrides direction and should be rare.'),
        S('Dates and annotations','time wraps a human-readable date or time and datetime supplies a machine-readable value. ruby, rt, and rp support pronunciation annotations used by some East Asian text. wbr marks a safe optional line-break opportunity inside a long token.')],
      `<p>Next class: <time datetime="2026-10-05T18:30:00+05:30">5 October at 6:30 PM</time></p>\n<p>User: <bdi>إبراهيم</bdi> — 42 points</p>\n<p lang="fr">Bonjour</p>`,
      [['lang','Language tag'],['dir="auto"','Direction from content'],['bdi','Bidirectional isolation'],['time datetime','Human and machine-readable date/time'],['wbr','Optional word-break opportunity']],
      ['Setting direction with CSS alone while omitting semantic direction','Hard-coding ambiguous numeric dates','Failing to isolate unknown-direction usernames'],
      'Create an event card containing localized language, an ISO datetime, a right-to-left speaker name, and a long URL with safe break points.',
      'Which element isolates unknown-direction user text?',['bdo','bdi','time','ruby'],1,'bdi prevents embedded bidirectional text from changing surrounding text order.'),

    L('performance','Quality','HTML loading and performance hints','Advanced','Help the browser prioritize critical resources without overusing hints.','performance preload prefetch preconnect fetchpriority lazy loading modulepreload dns','HTML influences loading through resource discovery order, hints, dimensions, and lazy-loading attributes.',
      ['Identify render-blocking resources','Use preload, modulepreload, preconnect, and prefetch appropriately','Prioritize the largest visible image','Reduce layout shift with dimensions and stable placeholders'],[
        S('Critical path','The browser discovers resources while parsing. CSS can block rendering; synchronous scripts can block parsing. Keep critical CSS focused, defer non-critical scripts, compress files, and avoid deep chains where one resource discovers another late.'),
        S('Resource hints','preload requests a required current-page resource early and needs a correct as value. modulepreload fetches module dependencies. preconnect prepares a connection to an important third-party origin; use it only for likely early requests. prefetch suggests a lower-priority future navigation resource.'),
        S('Images and stability','The largest above-the-fold image should normally load eagerly and may use fetchpriority="high" when discovery is late. Off-screen images and iframes may use loading="lazy". Intrinsic dimensions or aspect-ratio prevent cumulative layout shift.')],
      `<link rel="preconnect" href="https://fonts.example.com" crossorigin>\n<link rel="preload" href="hero.avif" as="image" type="image/avif">\n<img src="hero.avif" alt="Apex lesson dashboard" width="1200" height="700" fetchpriority="high">\n<img src="later-example.webp" alt="Completed code example" width="800" height="500" loading="lazy">`,
      [['preload','High-priority current-page resource'],['preconnect','Early connection setup'],['prefetch','Possible future resource'],['fetchpriority','Relative fetch priority hint'],['loading="lazy"','Deferred off-screen loading']],
      ['Preloading many resources and competing with truly critical work','Lazy-loading the largest visible image','Omitting image dimensions and accepting layout movement'],
      'Inspect a page network waterfall and propose three HTML changes that improve discovery, priority, or layout stability.',
      'Which hint is intended for a likely future navigation resource?',['preload','prefetch','canonical','alternate'],1,'prefetch is a low-priority hint for a resource likely needed later.'),

    L('security-privacy','Quality','HTML security and privacy boundaries','Advanced','Reduce injection, opener, embed, and referrer risks at the markup layer.','security xss csp sandbox noreferrer noopener referrerpolicy integrity crossorigin','HTML alone cannot secure an application, but several elements and attributes enforce important browser security boundaries.',
      ['Explain HTML injection and safe text handling','Limit embeds and referrer information','Use integrity and crossorigin for trusted external assets','Understand the purpose of Content Security Policy'],[
        S('Injection and unsafe markup','If untrusted text is inserted as HTML, it can create elements, event handlers, URLs, or scripts. Prefer textContent for plain text, sanitize trusted rich-text formats with a maintained sanitizer, and validate URLs. Escaping depends on context; HTML text, attributes, URLs, CSS, and JavaScript require different handling.'),
        S('Links, embeds, and referrers','New windows can interact with their opener in some situations; noopener prevents that relationship. noreferrer also suppresses referrer data. iframe sandbox and allow reduce embedded capabilities. referrerpolicy controls how much URL information a request reveals.'),
        S('Policy and external resources','Content Security Policy restricts which scripts, styles, images, frames, and connections may load and can block inline injection. Subresource Integrity verifies that a cross-origin script or stylesheet matches an expected hash; crossorigin is typically required with integrity. Policies supplement—not replace—safe output and authorization.')],
      `<meta http-equiv="Content-Security-Policy" content="default-src 'self'; img-src 'self' https:; object-src 'none'; base-uri 'self'">\n<a href="https://external.example" target="_blank" rel="noopener noreferrer">External reference</a>\n<iframe src="https://widgets.example" title="Course widget" sandbox="allow-scripts"></iframe>`,
      [['CSP','Restricts permitted resource sources'],['sandbox','Restricts an embedded document'],['referrerpolicy','Controls referrer information'],['integrity','Verifies external resource bytes'],['noopener','Breaks the opener relationship']],
      ['Rendering user input with innerHTML','Copying a permissive CSP that allows unsafe-inline everywhere','Assuming a hidden field or disabled button enforces authorization'],
      'Threat-model a page that renders comments and embeds a video. Identify injection, link, iframe, and referrer controls.',
      'What should render ordinary untrusted text in JavaScript?',['innerHTML','document.write','textContent','eval'],2,'textContent creates text rather than parsing the value as markup.'),

    L('validation-debugging','Quality','Validation, debugging, and maintainable HTML','Essential','Find structural errors and keep large documents understandable.','validator devtools lint duplicate id nesting source dom maintainability','Browsers recover from invalid markup, so a page may appear correct while its DOM, accessibility, or future behavior is broken.',
      ['Validate syntax and document conformance','Compare source code with the repaired DOM','Detect duplicate ids, missing labels, and broken references','Adopt formatting and naming conventions that support teamwork'],[
        S('Validation workflow','A validator catches forbidden nesting, missing attributes, duplicate ids, stray tags, and obsolete markup. Validation does not prove accessibility or good content, but it removes ambiguous structural failures. Treat warnings as prompts to understand, not merely silence.'),
        S('Debugging the parsed result','View Source shows the received HTML. The Elements panel shows the parsed and possibly script-modified DOM. If selectors, labels, or layout behave strangely, compare both. Browser accessibility tools reveal computed roles, names, states, and relationships.'),
        S('Maintainability habits','Use consistent indentation, lowercase element and attribute names, quoted values, semantic classes, and comments only where intent is not obvious. Break large pages into server or build templates, but inspect the final HTML sent to users. Test without CSS and without JavaScript to expose structural dependence.')],
      `<!-- Prefer readable structure over compressed source during development -->\n<section class="course-module" aria-labelledby="module-forms">\n  <h2 id="module-forms">Forms</h2>\n  <p>Labels, controls, validation, and submission.</p>\n</section>`,
      [['HTML validator','Checks document conformance'],['View Source','Original response source'],['Elements panel','Current parsed DOM'],['accessibility tree','Computed semantic interface'],['linting','Automated project conventions']],
      ['Stopping after “it looks fine” in one browser','Adding random closing tags until layout improves','Using duplicate ids generated by repeated templates'],
      'Run validation and an accessibility-tree inspection on a page, fix every structural error, and document one browser-repair behavior you found.',
      'Where can you inspect the browser-repaired document tree?',['View Source only','The Elements panel','The address bar','robots.txt'],1,'The Elements panel displays the current parsed DOM.'),

    L('progressive-enhancement','Architecture','Progressive enhancement and resilient documents','Advanced','Start with a meaningful document, then layer presentation and behavior.','progressive enhancement graceful degradation baseline no javascript resilience','Progressive enhancement makes the essential journey available with HTML and adds CSS and JavaScript where they improve it.',
      ['Design a useful HTML baseline','Enhance native links and forms without replacing their semantics','Handle script, network, and feature failure','Use feature detection rather than browser guessing'],[
        S('Baseline first','Begin with the content and task: readable information, navigable links, labeled fields, and a form action that can process submission. This baseline supports slow networks, blocked scripts, assistive technologies, search systems, and future code changes.'),
        S('Layered enhancement','CSS improves layout and visual clarity. JavaScript can add inline validation, filtering, partial updates, dialogs, and optimistic feedback while preserving the underlying URL or form action. If an enhancement requires different markup, keep the final semantics correct.'),
        S('Failure-aware design','Detect features directly, handle fetch rejection and timeouts, preserve user input, and show a recovery action. Avoid hiding usable content until initialization completes. Service workers, caches, and client routing are enhancements whose failure paths require deliberate testing.')],
      `<form action="/search" method="get" id="topic-search">\n  <label for="q">Search topics</label>\n  <input id="q" name="q" type="search">\n  <button>Search</button>\n</form>\n<script type="module">\n  if ('URLSearchParams' in window) {\n    // Enhance with instant local filtering; normal submission still works.\n  }\n<\/script>`,
      [['baseline','Essential non-enhanced experience'],['feature detection','Checking a capability directly'],['graceful failure','Useful recovery when enhancement fails'],['server-rendered','HTML produced before reaching the browser']],
      ['Rendering no content until JavaScript downloads','Using a div when a real link could provide navigation fallback','Testing only with a fast network and warm cache'],
      'Redesign a JavaScript-only search or menu so its essential task works with HTML, then describe the enhancement layer.',
      'What is the first layer in progressive enhancement?',['A JavaScript framework','Meaningful HTML and working core tasks','Animations','A service worker'],1,'The baseline is useful semantic HTML and the essential task.'),

    L('complete-page','Projects','Complete page architecture project','Project','Combine semantics, forms, media, accessibility, discovery, performance, and resilience.','project page architecture audit complete website checklist','A complete page is a system: document metadata, content hierarchy, navigation, media, interaction, performance, accessibility, and security decisions must reinforce one another.',
      ['Plan a page from user task to semantic outline','Implement a complete accessible document','Test structure, keyboard behavior, reflow, performance, and failure','Explain important architectural decisions'],[
        S('Plan before markup','Write the page purpose, primary user task, content outline, and navigation first. Identify repeated patterns, data-entry needs, essential media, and what should work before JavaScript. Choose elements from meaning rather than appearance.'),
        S('Build the system','Create unique metadata, labeled landmarks, a logical heading outline, descriptive links, responsive images, accessible forms, stable dimensions, and deliberate loading behavior. Add scripts as modules or deferred enhancements and keep external resources constrained.'),
        S('Verify like a user','Navigate with keyboard, zoom to 200–400%, test narrow reflow, disable images and scripts, validate HTML, inspect the accessibility tree, simulate a slow network, and confirm form errors preserve work. Record defects and retest after fixes.')],
      `<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Course catalog | Apex</title>\n  <meta name="description" content="Browse complete HTML, Python, and DBMS learning paths.">\n  <link rel="stylesheet" href="styles.css">\n  <script type="module" src="catalog.js"></script>\n</head>\n<body>\n  <header><a href="/">Apex</a><nav aria-label="Primary">…</nav></header>\n  <main id="main"><h1>Course catalog</h1><section aria-labelledby="courses">…</section></main>\n  <footer>…</footer>\n</body>\n</html>`,
      [['semantic outline','Meaningful hierarchy of regions and headings'],['acceptance criteria','Observable requirements for success'],['quality assurance','Planned testing against requirements'],['progressive enhancement','Layered resilient implementation']],
      ['Starting visual styling before deciding the content hierarchy','Calling the page finished after desktop mouse testing','Adding features without checking loading and failure behavior'],
      'Build a complete multi-section course page. Include metadata, landmarks, responsive media, a validated form, an interactive disclosure, and a written QA checklist.',
      'Which final test best exposes dependence on enhancement code?',['Increase monitor brightness','Disable JavaScript and try the core task','Change the favicon','Rename every class'],1,'Disabling JavaScript reveals whether the essential content and journey have a resilient baseline.')
  ];
})();
